diff --git a/kernel/bpf/arraymap.c b/kernel/bpf/arraymap.c
index 248ab6854cf2..9ee706cca548 100644
--- a/kernel/bpf/arraymap.c
+++ b/kernel/bpf/arraymap.c
@@ -8,6 +8,7 @@
 #include <linux/slab.h>
 #include <linux/mm.h>
 #include <linux/filter.h>
