 		if (attr->map_flags & BPF_F_MMAPABLE) {
 			array_size = PAGE_ALIGN(array_size);
-			array_size += PAGE_ALIGN((u64) max_entries * elem_size);
+			array_size += __PAGE_ALIGN((u64) max_entries * elem_size);
 		} else {
